public class Shell extends Application {                  // the view handler
    private final Map<String, Supplier<Parent>> screens = Map.of(
        "chart", () -> new ChartView(model), "table", () -> new TableView(model));
    private final BorderPane host = new BorderPane();
    private final Model model = new Model();

    public void open(String type) { host.setCenter(screens.get(type).get()); }  // create + switch
    public void closeAll() { for (Window w : Window.getWindows()) w.hide(); }   // dispose the set
    public void sync() {                                                       // model -> views
        for (Window w : Window.getWindows())
            if (w instanceof Stage s) s.getScene().getRoot().requestLayout();
    }
}

